package com.wartec.wartecmod.port;

import com.wartec.wartecmod.port.planning.*;
import com.wartec.wartecmod.port.entity.*;
import java.util.*;
import net.minecraft.init.Bootstrap;
import net.minecraft.nbt.*;
import org.junit.*;
import static org.junit.Assert.*;

public class CommandCenterTest {
    private final UUID commander=new UUID(109,1),operator=new UUID(109,2),observer=new UUID(109,3);
    @BeforeClass public static void bootstrap(){Bootstrap.register();}
    private CommandCenterState state(){CommandCenterState s=new CommandCenterState();s.roles.put(commander,CommandCenterState.Role.COMMANDER);return s;}
    private NBTTagCompound meta(){NBTTagCompound n=new NBTTagCompound();n.setString("Title","North battery");n.setString("Group","North");n.setInteger("Reserve",2);n.setInteger("ReserveTier",3);return n;}
    private AttackOperation operation(){AttackOperation o=new AttackOperation();o.scope="team:blue";o.author=commander;AttackOperation.Step s=new AttackOperation.Step();s.asset="e:"+new UUID(109,11);o.steps.add(s);return o;}
    private EntityStrategicMissile target(StrategicSystemProfile type,int x){EntityStrategicMissile m=new EntityStrategicMissile(null);m.configureReentry(type,0,x,64,0,new UUID(109,44),"red");return m;}
    @Test public void uninitializedCenterIsReadOnlyUntilTrustedOwnerBootstraps(){CommandCenterState s=new CommandCenterState();assertEquals(CommandCenterState.Role.OBSERVER,s.role(commander));assertFalse(CommandCenterService.mayMutate(s,commander,"start"));assertEquals("access",s.setRole(commander,commander,CommandCenterState.Role.COMMANDER));}
    @Test public void commanderGrantsOperatorsButObserversCannotWrite(){CommandCenterState s=state();assertEquals("",s.setRole(commander,operator,CommandCenterState.Role.OPERATOR));assertTrue(CommandCenterService.mayMutate(s,operator,"start"));assertFalse(CommandCenterService.mayMutate(s,operator,"cc_role"));assertFalse(CommandCenterService.mayMutate(s,observer,"save"));assertTrue(CommandCenterService.mayMutate(s,observer,"fetch"));assertEquals("access",s.setRole(operator,observer,CommandCenterState.Role.COMMANDER));}
    @Test public void lastCommanderCannotLoseTheTeam(){CommandCenterState s=state();assertEquals("last_commander",s.setRole(commander,commander,CommandCenterState.Role.OBSERVER));assertEquals("",s.setRole(commander,operator,CommandCenterState.Role.COMMANDER));assertEquals("",s.setRole(commander,commander,CommandCenterState.Role.OPERATOR));assertEquals(CommandCenterState.Role.COMMANDER,s.role(operator));}
    @Test public void corruptRoleDataDoesNotPromoteAnObserver(){CommandCenterState s=state();s.roles.clear();s.roles.put(observer,CommandCenterState.Role.OBSERVER);CommandCenterState copy=CommandCenterState.read(s.write());assertTrue(copy.roles.isEmpty());assertEquals(CommandCenterState.Role.OBSERVER,copy.role(observer));}
    @Test public void districtsAndFleetSurviveNbt(){CommandCenterState s=state();NBTTagCompound d=new NBTTagCompound();UUID id=new UUID(109,7);d.setUniqueId("Id",id);d.setString("Title","Airfield");d.setInteger("Radius",300);d.setDouble("X",10);assertEquals("",s.district(d));NBTTagCompound m=meta();m.setString("District",id.toString());assertEquals("",s.configure("e:test",m));CommandCenterState copy=CommandCenterState.read(s.write());assertEquals(id.toString(),copy.fleet.get("e:test").getString("District"));assertEquals("North",copy.fleet.get("e:test").getString("Group"));assertEquals(CommandCenterState.Role.COMMANDER,copy.role(commander));}
    @Test public void invalidDistrictNeverPartiallyChangesSettings(){CommandCenterState s=state();assertEquals("",s.configure("e:test",meta()));NBTTagCompound bad=meta();bad.setString("District",UUID.randomUUID().toString());assertEquals("district",s.configure("e:test",bad));assertEquals("",s.fleet.get("e:test").getString("District"));NBTTagCompound d=new NBTTagCompound();d.setDouble("X",Double.NaN);d.setInteger("Radius",300);assertEquals("coordinates",s.district(d));assertTrue(s.districts.isEmpty());}
    @Test public void removedDistrictClearsAssignments(){CommandCenterState s=state();NBTTagCompound d=new NBTTagCompound();UUID id=UUID.randomUUID();d.setUniqueId("Id",id);d.setInteger("Radius",64);s.district(d);NBTTagCompound m=meta();m.setString("District",id.toString());s.configure("e:test",m);s.removeDistrict(id);assertEquals("",s.fleet.get("e:test").getString("District"));}
    @Test public void labelsAloneNeverEnableCombatPolicy(){CommandCenterState s=state();NBTTagCompound m=meta();m.setInteger("Reserve",0);s.configure("e:test",m);assertFalse(s.hasPolicies());m.setInteger("Priority",1);s.configure("e:test",m);assertTrue(s.hasPolicies());m.setInteger("Priority",0);s.configure("e:test",m);assertFalse(s.hasPolicies());}
    @Test public void settingsAreBoundedAndCannotAddUnknownFields(){CommandCenterState s=state();NBTTagCompound m=meta();m.setString("Title",String.join("",Collections.nCopies(100,"a"))+"\n");m.setString("Role","COMMANDER");s.configure("e:test",m);assertEquals(64,s.fleet.get("e:test").getString("Title").length());assertFalse(s.fleet.get("e:test").hasKey("Role"));m.setInteger("Reserve",257);assertEquals("limits",s.configure("e:test",m));}
    @Test public void reserveIsReleasedForTheSelectedTier(){CommandCenterState s=state();PlanningAsset a=new PlanningAsset();a.ammo=2;NBTTagCompound m=meta();m.setInteger("ReserveTier",4);assertEquals("reserve",DefenseDoctrine.reason(a,m,s,target(StrategicSystemProfile.ISKANDER,0)));assertEquals("",DefenseDoctrine.reason(a,m,s,target(StrategicSystemProfile.TOPOL_M,0)));a.ammo=3;assertEquals("",DefenseDoctrine.reason(a,m,s,target(StrategicSystemProfile.ISKANDER,0)));}
    @Test public void districtUsesKnownImpactPointNotJustCurrentPosition(){CommandCenterState s=state();UUID id=UUID.randomUUID();NBTTagCompound d=new NBTTagCompound();d.setUniqueId("Id",id);d.setInteger("Radius",64);s.district(d);PlanningAsset a=new PlanningAsset();a.ammo=8;NBTTagCompound m=meta();m.setString("District",id.toString());assertEquals("district",DefenseDoctrine.reason(a,m,s,target(StrategicSystemProfile.TOPOL_M,1000)));assertEquals("",DefenseDoctrine.reason(a,m,s,target(StrategicSystemProfile.TOPOL_M,20)));}
    @Test public void repeatedWarningsDoNotSpamButChangedOutcomeIsImmediate(){CommandCenterState s=state();s.notify("t","incoming","e:x",100);long revision=s.revision;s.notify("t","incoming","e:x",101);assertEquals(revision,s.revision);s.notify("t","breakthrough","e:x",110);assertEquals("breakthrough",s.alerts.get("t").getString("Kind"));assertEquals(1,s.alerts.size());}
    @Test public void warningsStayAcknowledgedAcrossRestartIfStateDoesNotChange(){CommandCenterState s=state();PlanningAsset a=new PlanningAsset();a.key="e:x";a.loaded=true;a.attack=true;s.observe(a,20);s.acknowledge("asset:e:x");CommandCenterState copy=CommandCenterState.read(s.write());copy.observe(a,1000);assertTrue(copy.alerts.get("asset:e:x").getBoolean("Acknowledged"));}
    @Test public void warningArchiveAndSupplyTasksAreBounded(){CommandCenterState s=state();for(int i=0;i<200;i++)s.notify("k"+i,"empty","e:x",i*201);assertEquals(CommandCenterState.MAX_ALERTS,s.alerts.size());UUID first=s.task("e:x","ammo","Support",0);assertEquals(first,s.task("e:x","ammo","Support",1));assertTrue(s.completeTask(first));assertNotEquals(first,s.task("e:x","ammo","Support",2));}
    @Test public void worldDataSeparatesTeamSettings(){PlanningWorldData d=new PlanningWorldData();d.command("team:blue").roles.put(commander,CommandCenterState.Role.COMMANDER);d.command("team:red").configure("e:red",meta());PlanningWorldData copy=new PlanningWorldData();copy.readFromNBT(d.writeToNBT(new NBTTagCompound()));assertEquals(CommandCenterState.Role.COMMANDER,copy.command("team:blue").role(commander));assertTrue(copy.command("team:blue").fleet.isEmpty());assertFalse(copy.command("team:red").fleet.isEmpty());}
    @Test public void conditionsRoundTripAndLegacyPlansDefaultToNone(){AttackOperation o=operation();AttackOperation.Step s=o.steps.get(0);s.condition=AttackOperation.Condition.GROUP_READY;s.conditionGroup="North";s.intelAge=400;assertEquals("",o.validate());AttackOperation copy=AttackOperation.read(o.write());assertEquals(AttackOperation.Condition.GROUP_READY,copy.steps.get(0).condition);assertEquals("North",copy.steps.get(0).conditionGroup);NBTTagCompound old=s.write();old.removeTag("Condition");old.removeTag("IntelAge");assertEquals(AttackOperation.Condition.NONE,AttackOperation.Step.read(old).condition);}
    @Test public void emptyConditionGroupAndUnboundedAgeAreRejected(){AttackOperation o=operation();o.steps.get(0).condition=AttackOperation.Condition.GROUP_READY;assertEquals("condition",o.validate());o.steps.get(0).conditionGroup="A";o.steps.get(0).intelAge=0;assertEquals("condition",o.validate());}
    @Test public void physicalReadinessIncludesTheAbmEnergyCost(){PlanningAsset a=new PlanningAsset();a.loaded=true;a.kind="pvo";a.state="guard";a.tier=4;a.ammo=1;a.network=true;a.power=100000;assertFalse(CommandConditions.ready(a));a.power=200000;assertTrue(CommandConditions.ready(a));}
    @Test public void timelineUsesActualEventsAndKeepsAcceptedTimesDuringPause(){AttackOperation o=operation();o.started=100;AttackOperation.Step first=o.steps.get(0);first.accepted=110;first.actual=160;AttackOperation.Step next=new AttackOperation.Step();next.asset=first.asset;next.after=first.id;next.offset=20;o.steps.add(next);Map<UUID,Long> duration=new HashMap<>();duration.put(first.id,120L);assertEquals(80,OperationTimeline.start(o,next,duration,Collections.emptyMap()));o.clockOffset=300;assertEquals(10,OperationTimeline.start(o,first,duration,Collections.emptyMap()));}
    @Test public void timelineFlagsIndependentOrdersButNotDependencies(){AttackOperation o=operation();AttackOperation.Step a=o.steps.get(0),b=new AttackOperation.Step();b.asset=a.asset;o.steps.add(b);assertEquals(2,OperationTimeline.conflicts(o,Collections.emptyMap(),Collections.emptyMap()).size());b.after=a.id;assertTrue(OperationTimeline.conflicts(o,Collections.emptyMap(),Collections.emptyMap()).isEmpty());}
    @Test public void observationHistoryAndSavedViewNeverReadTheCurrentWorld(){TeamIntelData d=new TeamIntelData();d.cell(0,0,64,0x228844,100,"EO",commander);d.contact("x","PVO","vehicle",0,64,0,1,120,"EO",commander);assertEquals(0x228844,d.contacts.get("x").getIntArray("Patch")[5]);d.cell(0,0,65,0xeeeeee,200,"EO",commander);assertEquals(0x228844,d.contacts.get("x").getIntArray("Patch")[5]);d.contact("x","PVO","vehicle",20,64,0,1,220,"EO",commander);assertEquals(1,d.contacts.get("x").getTagList("History",10).tagCount());assertEquals(0x228844,d.contacts.get("x").getTagList("History",10).getCompoundTagAt(0).getIntArray("Patch")[5]);}
    @Test public void lateObservationCannotBorrowFutureTerrain(){TeamIntelData d=new TeamIntelData();d.cell(0,0,64,0x228844,200,"EO",commander);d.contact("x","PVO","vehicle",0,64,0,1,100,"EO",commander);assertEquals(0,d.contacts.get("x").getIntArray("Patch")[5]);}
    @Test public void resurveyPreservesOldObservationAsHistory(){TeamIntelData d=new TeamIntelData();d.contact("x","PVO","vehicle",0,64,0,1,100,"EO",commander);d.markUnconfirmed("x",120);assertFalse(d.contacts.get("x").getBoolean("Confirmed"));assertEquals(1,d.contacts.get("x").getTagList("History",10).tagCount());d.markUnconfirmed("x",130);assertEquals(1,d.contacts.get("x").getTagList("History",10).tagCount());}
    @Test public void replayDistinguishesDetectionLaunchAndActualOutcome(){DefenseBattleLog d=new DefenseBattleLog();UUID target=UUID.randomUUID(),shot=UUID.randomUUID();d.track(target,100);d.shot(shot,"e:pvo","PVO",target,120);d.outcome(shot,target,true,150);NBTTagList events=d.replay(target).getTagList("Events",10);assertEquals(4,events.tagCount());assertEquals("identified",events.getCompoundTagAt(0).getString("Outcome"));assertEquals("launched",events.getCompoundTagAt(1).getString("Outcome"));assertEquals(120,events.getCompoundTagAt(1).getLong("Tick"));assertTrue(d.replay(UUID.randomUUID()).hasNoTags());}
    @Test public void trajectoriesHaveFiniteStorage(){NBTTagCompound row=new NBTTagCompound();for(int i=0;i<100;i++)DefenseBattleLog.sample(row,i,64,0,i*20);assertEquals(100,row.getTagList("Trace",10).tagCount());}
}
